import Link from "next/link";
export function AdminNotice() {
  return (
    <p role="alert">
      Admin data is unavailable or the filters are invalid. Refresh and try
      again.
    </p>
  );
}
export function dateLabel(value: string | null) {
  return value
    ? new Date(value).toISOString().replace("T", " ").replace(".000Z", " UTC")
    : "Unknown";
}
export function CursorLink({
  path,
  cursor,
  filters = {},
}: {
  path: string;
  cursor: string | null;
  filters?: Record<string, string | undefined>;
}) {
  const q = new URLSearchParams();
  for (const [k, v] of Object.entries(filters))
    if (v && k !== "cursor") q.set(k, v);
  if (cursor) q.set("cursor", cursor);
  return (
    <nav aria-label="Pagination" className="mt-6 flex gap-6">
      <Link href={path}>Reset pagination</Link>
      {cursor && <Link href={`${path}?${q}`}>Next 50 →</Link>}
    </nav>
  );
}
